	for (int i = 0; i <= n; ++i) vis[i] = in_o[i] = e[i] = o[i] = a[i] = 0;

	int cnt = 0;
	for (int i = 0; i < n; ++i) {
		if (vis[i]) continue;
		int j = i ^ x;
		vis[i] = vis[j] = 1;
		p[++cnt] = {i, j};
	}

	for (int i = 1; i <= n / 4; ++i) in_o[p[i].first] = in_o[p[i].second] = 1;

	int ec = 0, oc = 0;
	for (int i = 0; i < n; ++i) {
		if (in_o[i]) o[++oc] = i;
		else e[++ec] = i;
	}

	ec = oc = 0;
	for (int i = 0; i < n; ++i) {
		if (i & 1) a[i] = o[++oc];
		else a[i] = e[++ec];
	}

	for (int i = 0; i < n; ++i) {
		for (int j = 0; j < n; ++j) {
			int v = a[i] ^ a[j];
