#include <bits/stdc++.h>
using namespace std;

struct node {
	long long v = 0;
	bool b = 0;
	string l = "", r = "";
	int l1, r1;
};

int n, k;
int fai[2000005];
long long T, ql, qr, trans[10][10];
long long ma, L, R;
node a[66][10], ans;
string pl[10], pr[10], s;

void make_fai() {
	for (int i = 1; i <= n; ++i) s[i] ^= 48;

	int l = 0;
	for (int i = 2; i <= n; ++i) {
		while (l && s[l + 1] != s[i]) l = fai[l];
		l += s[l + 1] == s[i];
		fai[i] = l;
	}
}

int val(string x) {
	int l = 0, res = 0;

	for (int i = 0; i < (int)x.size(); ++i) {
		while (l && s[l + 1] != x[i]) l = fai[l];
		l += s[l + 1] == x[i];
		if (l == n) ++res;
	}

	return res;
}

node add(node &x, node &y) {
	node res;

	if (x.b && y.b) {
		res.b = 1;
		res.l1 = x.l1;
		res.r1 = y.r1;
		res.v = x.v + y.v + trans[x.r1][y.l1];
		return res;
	}

	if (x.b) x.l = pl[x.l1], x.r = pr[x.r1];
	if (y.b) y.l = pl[y.l1], y.r = pr[y.r1];
	res.v = x.v + y.v + val(x.r + y.l);
	res.l = x.l;

	if ((int)res.l.size() < n - 1) {
		int t = min(n - 1 - (int)res.l.size(), (int)y.l.size());
		res.l += y.l.substr(0, t);
	}

	res.r = y.r;
	if ((int)res.r.size() < n - 1) {
		int t = min(n - 1 - (int)res.r.size(), (int)x.r.size());
		res.r = x.r.substr(x.r.size() - t, t) + res.r;
	}

	return res;
}

void init(long long x) {
	bool done = 0;

	for (long long cur = 1, i = 0; cur <= x; cur *= k, ++i) {
		ma = i;
		L = 0, R = cur;

		if (i == 0) {
			for (int j = 0; j < k; ++j) {
				if (n == 1) {
					a[0][j].v = j == s[1];
					a[0][j].b = 0;
					a[0][j].l = a[0][j].r = "";
				}
				else {
					a[0][j].v = 0;
					a[0][j].b = 0;
					a[0][j].l = a[0][j].r = "";
					a[0][j].l += (char)j;
					a[0][j].r = a[0][j].l;
				}
			}
		}
		else {
			for (int j = 0; j < k; ++j) {
				node cur;
				for (int t = 0; t < k; ++t) {
					if (!cur.v && !cur.b && cur.l.empty()) cur = a[i - 1][(j + t) % k];
					else cur = add(cur, a[i - 1][(j + t) % k]);
				}
				a[i][j] = cur;
			}
		}

		if (!done && cur >= n - 1) {
			done = 1;
			for (int j = 0; j < k; ++j) {
				pl[j] = a[i][j].l;
				pr[j] = a[i][j].r;
				a[i][j].b = 1;
				a[i][j].l1 = a[i][j].r1 = j;
				a[i][j].l = a[i][j].r = "";
			}
			for (int j = 0; j < k; ++j) {
				for (int t = 0; t < k; ++t) trans[j][t] = val(pr[j] + pl[t]);
			}
		}
	}
}

void calc(int dep, int st, long long l, long long r) {
	if (r <= ql || l > qr) return;

	if (ql <= l && r - 1 <= qr) {
		ans = add(ans, a[dep][st]);
		return;
	}

	node cur;
	long long len = r - l;

	for (int i = 0; i < k; ++i) {
		long long nl = l + len / k * i, nr = nl + len / k;

		if (ql <= nl && nr - 1 <= qr) {
			if (!cur.v && !cur.b && cur.l.empty()) cur = a[dep - 1][(st + i) % k];
			else cur = add(cur, a[dep - 1][(st + i) % k]);
			continue;
		}

		if (cur.v || cur.b || !cur.l.empty()) {
			ans = add(ans, cur);
			cur.v = 0, cur.b = 0;
			cur.l = cur.r = "";
		}
		calc(dep - 1, (st + i) % k, nl, nr);
	}

	if (cur.v || cur.b || !cur.l.empty()) ans = add(ans, cur);
}

int main() {
	ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);

	cin >> k >> T;
	while (T--) {
		cin >> ql >> qr >> n >> s;
		s = " " + s + "!";

		make_fai();
		init(qr);
		++ma, R *= k;

		ans.v = 0, ans.b = 0;
		ans.l = ans.r = "";
		calc(ma, 0, L, R);
		cout << ans.v << '\n';
	}

	return 0;
}

#include<bits/stdc++.h>
#define int long long
using namespace std;
int lg;
int q,L,R,n,k,d[10000005],t[100],b[100];
char c[10000005],s[10000005];
struct node{
	int f[65][65];
}sum[65][65];
node merge(node a,node b,int v=1){
	for(int i=0;i<k;i++){
		for(int j=0;j<k;j++){
			a.f[(i+v)%k][(j+v)%k]+=b.f[i][j];
		}
	}
	return a;
}
int calc(int x){
	int sum=0;
	while(x){
		sum+=x%k;
		x=x/k;
	}
	return sum%k;
}
int sp[70];
int gs(int r,int x,int y){
    // Count occurrences of the pattern "xy" in the range [0, r].
	r++;
	int cnt=0,xnow=0,ans=0,lowbit=0;
	for(int i=0;i<=lg;i++){
		sp[i]=r%k;r/=k;
	}
	for(int i=lg;i>=0;i--){
		int j=sp[i];
		if(!j) continue;
		ans+=sum[i][j].f[(x+(k-1)*cnt)%k][(y+(k-1)*cnt)%k];
		if(xnow){
			int px=(cnt-1+lowbit*(k-1))%k,py=cnt%k;
			if(px==x&&py==y){
				ans++;
			}
		}
		xnow+=b[i]*j;
		cnt+=j;
		lowbit=i;
	}
	return ans;
}
int gs(int r,int x){
    // Count occurrences of the pattern "x" in the range [0, r].
	r++;
	int sum=r/k,pl=r/k*k,y=calc(pl);
	while(pl<r){
		if(y==x){
			sum++;
			break;
		}
		pl++;
		y++;
		y>=k?y-=k:0;
	}
	return sum;
}
void print(char c){
	if(c<10){
		cout<<char(c+'0');
	}else{
		cout<<char(c+'a'-10);
	}
}
int ans=0;
void solve(int l,int r,int n){
    // Compute the answer recursively.
	if(l>r){
		return ;
	}
	for(int i=0;i<k;i++){
		t[i]=0;
	}
	if(n<=2){
        // For length at most 2, use prefix-count differences directly.
		if(n==2){
			int pl=c[0],pr=c[1];
			int sum=gs(r,pl,pr)-gs(l,pl,pr);
			ans+=sum;
			return ;
		}else{
			int sum=0;
			sum=gs(r,c[0])-gs(l-1,c[0]);
			ans+=sum;
			return ;
		}
	}
	int cnt=0;
	for(int i=1;i<n;i++){
		d[i]=(c[i]-c[i-1]+k)%k;
		if(d[i]!=1){
			if(!t[i%k]) cnt++;
			t[i%k]=1;
		}
	}
	if(cnt>1){
        // If more than one residue occurs, the pattern cannot appear.
		return ;
	}
	int m=0,pl=k,pr=k,p=0;
	if(cnt){
        // At least one adjacent difference is not 1.
		for(int i=1;i<n;i++){
			if(d[i]!=1) p=i%k;
		}
		if(p){
			pl=p;
			s[m++]=(c[p-1]+1)%k;
		}
		for(int i=p;i<n;i+=k){
			if(i+k-1>=n) pr=n-i;
			s[m++]=c[i];
		}

        // Handle the two partial boundary blocks separately.
		int bl=(r/k)*k,br=(l/k+1)*k-1;
		if(br-l+1<pl) l=l/k+1;
		else l=l/k;
		if(r-bl+1<pr) r=r/k-1;
		else r=r/k;

		for(int i=0;i<m;i++) c[i]=s[i];
		solve(l,r,m);
	}else{
        // Every adjacent difference is 1.
		int szl=(l/k+1)*k-l,szr=r-(r/k)*k+1,L,R;
		if(n<=k){
			int x=c[0];
			for(int i=0;i+n-1<k;i++){
				c[0]=(x-i+k)%k;
                // Handle the two partial boundary blocks separately.
				pl=k-i,pr=i+n;
				if(szl<pl) L=l/k+1;
				else L=l/k;
				if(szr<pr) R=r/k-1;
				else R=r/k;
				solve(L,R,1);
			}
		}
		for(int i=0;i<n;i++){
			s[i]=c[i];
		}
		for(int i=0;i<min(n-1,k);i++){
            // Handle the two partial boundary blocks separately.
			pl=i+1,pr=n-1-i;
			if(pr>k) continue;
			if(szl<pl) L=l/k+1;
			else L=l/k;
			if(szr<pr) R=r/k-1;
			else R=r/k;
			c[0]=c[1]=s[i+1];
			solve(L,R,2);
		}
	}
}
char change(int x){
    if(0<=x&&x<=9) return x+'0';
    if(10<=x&&x<=35) return x-10+'A';
    if(36<=x&&x<=61) return x-36+'a';
}
int change(char x){
    if('0'<=x&&x<='9') return x-'0';
    if('A'<=x&&x<='Z') return x+10-'A';
    if('a'<=x&&x<='z') return x+36-'a';
}
signed main(){
	ios::sync_with_stdio(0);
	cin.tie(0);cout.tie(0);
	cin>>k>>q;

    // sum[i][j] stores counts of length-2 substrings in the first j * k^i characters.
	b[0]=1;lg=0;
	for(int i=1;i<=k;i++){
		for(int j=1;j<i;j++){
			sum[0][i].f[j-1][j]=1;
		}
	}
	for(int p=1;p;p++){
		b[p]=b[p-1]*k;
		lg++;
		if(b[p]>1e17){
			break;
		}
		sum[p][1]=sum[p-1][k];
        // Concatenate the k shifted blocks.
		for(int i=2;i<=k;i++){
			sum[p][i]=merge(sum[p][i-1],sum[p-1][k],i-1);
			// Count substrings that cross a block boundary directly.
			sum[p][i].f[calc(b[p]*(i-1)-1)][calc(b[p]*(i-1))]++;
		}
	}

	while(q--){
		cin>>L>>R>>n;
		cin>>c;
		for(int i=0;i<n;i++){
			c[i]=change(c[i]);
		}
		solve(L,R,n);
		cout<<ans<<endl;
		ans=0;
	}
    return 0;
}

